export interface Interface {
  readonly find: (input: FindInput) => Effect.Effect<readonly Entry[], Error>
  readonly glob: (input: GlobInput) => Effect.Effect<SearchResult<Entry>, Error> // kilocode_change
  readonly grep: (input: GrepInput) => Effect.Effect<SearchResult<KiloGrep.GrepMatch>, Error | InvalidPatternError> // kilocode_change
}

// kilocode_change start - retain truncation state through model-facing tools
export interface SearchResult<A> {
  readonly items: readonly A[]
  readonly truncated: boolean
  readonly partial: boolean
}
// kilocode_change end

export class Service extends Context.Service<Service, Interface>()("@opencode/v2/Ripgrep") {}

const failure = (message: string, cause?: unknown) => new Error({ message, cause })

const isInvalidPattern = (stderr: string) =>
  stderr.includes("regex parse error") || stderr.includes("error parsing regex")

const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const process = yield* AppProcess.Service
    const binary = yield* RipgrepBinary.Service

    const run = <A>(input: {
      readonly cwd: string
      readonly args: string[]
      readonly limit: number
      readonly signal?: AbortSignal
      readonly timeout?: number // kilocode_change
      readonly parse: (line: string) => Effect.Effect<A | undefined, Error>
      readonly pattern?: string
      readonly onItem?: (item: A) => Effect.Effect<void>
      readonly stop?: (item: A) => boolean // kilocode_change - stop bounded searches at the overflow match
      readonly validate?: Effect.Effect<void, unknown> // kilocode_change - spawn-bound target validation
    }) => {
      const program = Effect.scoped(
        Effect.gen(function* () {
          const filepath = yield* binary.filepath
          // kilocode_change start - validate approved targets after all spawn preparation
          const command = ChildProcess.make(filepath, input.args, {
            cwd: input.cwd,
            extendEnv: true,
            stdin: "ignore",
            forceKillAfter: input.stop || input.timeout != null ? Duration.seconds(1) : undefined, // kilocode_change - bound search interruption
          })
          const validated = input.validate ? SpawnValidation.attach(command, input.validate) : command
          const spawned = input.stop || input.timeout != null ? SpawnExit.attach(validated) : validated // kilocode_change
          const handle = yield* process.spawn(spawned)
          const search = Effect.gen(function* () {
            // kilocode_change end
            const stderrFiber = yield* collectStream(handle.stderr, ERROR_BYTES).pipe(
              Effect.map((output) => output.buffer.toString("utf8")),
              Effect.forkScoped,
            )
            let observed = 0
            let stopped = false // kilocode_change
            const take = input.stop // kilocode_change start
              ? Stream.takeUntil<A>((row) => {
                  stopped = input.stop?.(row) ?? false
                  return stopped
                })
              : Stream.take(input.limit + 1) // kilocode_change end
            const rows = yield* Stream.decodeText(handle.stdout).pipe(
              Stream.splitLines,
              Stream.filter((line) => line.length > 0),
              Stream.mapEffect(input.parse),
              Stream.filter((row): row is A => row !== undefined),
              Stream.tap((row) => {
                if (!input.onItem || observed++ >= input.limit) return Effect.void
                return input.onItem(row)
              }),
              take, // kilocode_change
              Stream.runCollect,
              Effect.map((chunk) => [...chunk]),
            )
            if (stopped) return { items: rows, truncated: true, partial: false } // kilocode_change
            const truncated = input.stop ? false : rows.length > input.limit // kilocode_change - custom stop owns truncation
            if (truncated) return { items: rows.slice(0, input.limit), truncated, partial: false }

            const code = yield* handle.exitCode
            const stderr = yield* Fiber.join(stderrFiber)
            if (input.pattern && code === 2 && isInvalidPattern(stderr)) {
              return yield* new InvalidPatternError({ pattern: input.pattern, message: stderr.trim() })
            }
            if (code !== 0 && code !== 1 && code !== 2) {
              return yield* failure(stderr.trim() || `ripgrep failed with code ${code}`)
            }
            return { items: code === 1 ? [] : rows, truncated: false, partial: code === 2 }
            // kilocode_change start
          })
          return yield* input.timeout == null
            ? search
            : search.pipe(
                Effect.timeoutOrElse({
                  duration: input.timeout,
                  orElse: () =>
                    Effect.fail(failure("Glob search timed out after 2 minutes. Narrow the search path or pattern.")),
                }),
              )
          // kilocode_change end
        }),
      )
      const abortable = input.signal ? program.pipe(Effect.raceFirst(waitForAbort(input.signal))) : program
      return abortable.pipe(
        // kilocode_change start - surface the underlying reason instead of a bare wrapper message
        Effect.mapError((cause) => {
          if (cause instanceof Error || cause instanceof InvalidPatternError) return cause
          const detail = cause instanceof globalThis.Error && cause.message.trim() ? `: ${cause.message.trim()}` : ""
          return failure(`ripgrep execution failed${detail}`, cause)
        }),
        // kilocode_change end
      )
    }

    return Service.of({
      glob: (input) =>
        run<string>({
          cwd: input.cwd,
          limit: input.limit,
          signal: input.signal,
          timeout: 2 * 60 * 1000, // kilocode_change
          validate: input.validate, // kilocode_change - preserve spawn-bound target validation
          args: [
            "--no-config",
            "--files",
            ...(input.hidden ? ["--hidden"] : []),
            ...(input.follow ? ["--follow"] : []),
            `--glob=${input.pattern}`,
            "--glob=!**/.git/**",
            ".",
          ],
          parse: (line) =>
            Effect.succeed(
              line
                .replace(/^(?:\.[\\/])+/u, "")
                .replace(/^[\\/]+/u, "")
                .replaceAll("\\", "/"),
            ),
        }).pipe(
          // kilocode_change start - retain spawn metadata after mapping paths
          Effect.map((result) => ({
            ...result,
            items: result.items.map((relative) =>
              Entry.make({
                path: RelativePath.make(relative),
                type: "file",
              }),
            ),
          })),
          // kilocode_change end
          Effect.catchTag("Ripgrep.InvalidPatternError", (cause) => Effect.fail(failure(cause.message, cause))),
        ),
      find: (input) =>
        run<Entry>({
          cwd: input.cwd,
          limit: input.limit,
          signal: input.signal,
          args: [
            "--no-config",
            "--files",
            ...(input.hidden ? ["--hidden"] : []),
            ...(input.follow ? ["--follow"] : []),
            ...(input.pattern === "*" ? [] : [`--glob=${input.pattern}`]),
            "--glob=!**/.git/**",
            ".",
          ],
          parse: (line) => {
            const relative = line
              .replace(/^(?:\.[\\/])+/u, "")
              .replace(/^[\\/]+/u, "")
              .replaceAll("\\", "/")
            return Effect.succeed(
              Entry.make({
                path: RelativePath.make(relative),
                type: "file",
              }),
            )
          },
          onItem: input.onEntry,
        }).pipe(
          Effect.map((result) => result.items),
          Effect.catchTag("Ripgrep.InvalidPatternError", (cause) => Effect.fail(failure(cause.message, cause))),
        ),
      grep: (input) =>
        run<RawMatchData>({
          ...input,
          stop: KiloGrep.stop(input.limit), // kilocode_change
          args: [
            "--no-config",
            "--json",
            "--hidden",
            "--no-messages",
            ...KiloGrep.flags(input), // kilocode_change
            ...(input.include ? [`--glob=${input.include}`] : []),
            "--glob=!**/.git/**",
            "--",
            input.pattern,
            input.file ?? ".",
          ],
          parse: (line) =>
            (Buffer.byteLength(line, "utf8") > MAX_RECORD_BYTES
              ? Effect.fail(failure(`Ripgrep JSON record exceeded ${MAX_RECORD_BYTES} bytes`))
              : Effect.try({
                  try: () => JSON.parse(line) as unknown,
                  catch: (cause) => failure("Invalid ripgrep JSON output", cause),
                })
            ).pipe(
              Effect.flatMap((json) => {
                if (
                  !json ||
                  typeof json !== "object" ||
                  !("type" in json) ||
                  (json.type !== "match" && json.type !== "context") // kilocode_change
                )
                  return Effect.succeed(undefined)
                return Schema.decodeUnknownEffect(RawMatch)(json).pipe(
                  Effect.map((match) => ({
                    ...match.data,
                    path: { text: match.data.path.text.replace(/^\.[\\/]/, "") },
                    submatches: match.data.submatches.slice(0, MAX_SUBMATCHES),
                    context: match.type === "context", // kilocode_change
                  })),
                  Effect.mapError((cause) => failure("Invalid ripgrep match output", cause)),
                )
              }),
            ),
        }).pipe(
          // kilocode_change start - retain spawn metadata after mapping matches
          Effect.map((result) => ({
            ...result,
            items: KiloGrep.select(input, result.items).map((match) => {
              const relative = match.path.text
                .replace(/^(?:\.[\\/])+/u, "")
                .replace(/^[\\/]+/u, "")
                .replaceAll("\\", "/")
              const item = Match.make({
                entry: Entry.make({
                  path: RelativePath.make(relative),
                  type: "file",
                }),
                line: match.line_number,
                offset: match.absolute_offset,
                text: match.lines.text.length > 2_000 ? match.lines.text.slice(0, 2_000) + "..." : match.lines.text,
                submatches: match.submatches.map((submatch) => ({
                  text: submatch.match.text,
                  start: submatch.start,
                  end: submatch.end,
                })),
              })
              return KiloGrep.decorate(item, match.context, match.lines.text.length > 2_000)
            }),
          })),
          // kilocode_change end
        ),
    })
  }),
)

export const node = makeGlobalNode({ service: Service, layer: layer, deps: [RipgrepBinary.node, AppProcess.node] })

import type { Match } from "@opencode-ai/schema/filesystem"

export interface Options {
  readonly context?: number
  readonly literal?: boolean
  readonly ignoreCase?: boolean
}

export type GrepMatch = Match & {
  readonly context: boolean
  readonly textTruncated: boolean
}

export const flags = (input: Options) => [
  ...(input.literal ? ["--fixed-strings"] : []),
  ...(input.ignoreCase ? ["--ignore-case"] : []),
  ...(input.context ? [`--context=${input.context}`] : []),
]

export const stop = (limit: number) => {
  let matches = 0
  return (row: { readonly context: boolean }) => !row.context && ++matches > limit
}

export const select = <
  A extends {
    readonly context: boolean
    readonly path: { readonly text: string }
    readonly line_number: number
  },
>(
  input: { readonly limit: number; readonly context?: number },
  items: readonly A[],
) => {
  let count = 0
  const overflow = items.findIndex((row) => !row.context && ++count > input.limit)
  const selected = items.slice(0, overflow === -1 ? items.length : overflow)
  const matches = selected.filter((row) => !row.context)
  return selected.filter(
    (row) =>
      !row.context ||
      matches.some(
        (match) =>
          match.path.text === row.path.text && Math.abs(match.line_number - row.line_number) <= (input.context ?? 0),
      ),
  )
}

export const decorate = (match: Match, context: boolean, textTruncated: boolean): GrepMatch =>
  Object.assign(match, { context, textTruncated })

import path from "path"
import { Context, Effect, Layer, Stream } from "effect"
import { FetchHttpClient, HttpClient, HttpClientRequest } from "effect/unstable/http"
import { ChildProcess } from "effect/unstable/process"
import { ChildProcessSpawner } from "effect/unstable/process/ChildProcessSpawner"
import { CrossSpawnSpawner } from "../cross-spawn-spawner"
import { makeGlobalNode } from "../effect/app-node"
import { httpClient } from "../effect/app-node-platform"
import { FSUtil } from "../fs-util"
import { Global } from "../global"
import { which } from "../util/which"

export namespace RipgrepBinary {
  const VERSION = "15.1.0"
  const PLATFORM = {
    "arm64-darwin": { platform: "aarch64-apple-darwin", extension: "tar.gz" },
    "arm64-linux": { platform: "aarch64-unknown-linux-gnu", extension: "tar.gz" },
    "x64-darwin": { platform: "x86_64-apple-darwin", extension: "tar.gz" },
    "x64-linux": { platform: "x86_64-unknown-linux-musl", extension: "tar.gz" },
    "arm64-win32": { platform: "aarch64-pc-windows-msvc", extension: "zip" },
    "ia32-win32": { platform: "i686-pc-windows-msvc", extension: "zip" },
    "x64-win32": { platform: "x86_64-pc-windows-msvc", extension: "zip" },
  } as const

  interface Interface {
    readonly filepath: Effect.Effect<string, Error>
  }

  export class Service extends Context.Service<Service, Interface>()("@opencode/RipgrepBinary") {}

  const layer = Layer.effect(
    Service,
    Effect.gen(function* () {
      const fs = yield* FSUtil.Service
      const http = HttpClient.filterStatusOk(yield* HttpClient.HttpClient)
      const spawner = yield* ChildProcessSpawner

      const run = Effect.fnUntraced(function* (command: string, args: string[]) {
        const handle = yield* spawner.spawn(ChildProcess.make(command, args, { extendEnv: true, stdin: "ignore" }))
        const [stdout, stderr, code] = yield* Effect.all(
          [
            Stream.mkString(Stream.decodeText(handle.stdout)),
            Stream.mkString(Stream.decodeText(handle.stderr)),
            handle.exitCode,
          ],
          { concurrency: "unbounded" },
        )
        return { stdout, stderr, code }
      }, Effect.scoped)

      const extract = Effect.fnUntraced(function* (
        archive: string,
        config: (typeof PLATFORM)[keyof typeof PLATFORM],
        target: string,
      ) {
        const dir = yield* fs.makeTempDirectoryScoped({ directory: Global.Path.bin, prefix: "ripgrep-" })

        if (config.extension === "zip") {
          const shell = (yield* Effect.sync(() => which("powershell.exe") ?? which("pwsh.exe"))) ?? "powershell.exe"
          const result = yield* run(shell, [
            "-NoProfile",
            "-NonInteractive",
            "-Command",
            `$global:ProgressPreference = 'SilentlyContinue'; Expand-Archive -LiteralPath '${archive.replaceAll("'", "''")}' -DestinationPath '${dir.replaceAll("'", "''")}' -Force`,
          ])
          if (result.code !== 0)
            throw new Error(
              result.stderr.trim() || result.stdout.trim() || `ripgrep extraction failed with code ${result.code}`,
            )
        }

        if (config.extension === "tar.gz") {
          const result = yield* run("tar", ["-xzf", archive, "-C", dir])
          if (result.code !== 0)
            throw new Error(
              result.stderr.trim() || result.stdout.trim() || `ripgrep extraction failed with code ${result.code}`,
            )
        }

        const extracted = path.join(
          dir,
          `ripgrep-${VERSION}-${config.platform}`,
          process.platform === "win32" ? "rg.exe" : "rg",
        )
        if (!(yield* fs.isFile(extracted))) throw new Error(`ripgrep archive did not contain executable: ${extracted}`)

        yield* fs.copyFile(extracted, target)
        if (process.platform !== "win32") yield* fs.chmod(target, 0o755)
      }, Effect.scoped)

      return Service.of({
        filepath: yield* Effect.cached(
          Effect.gen(function* () {
            // kilocode_change - Git for Windows may expose an incompatible MSYS rg.exe
            const system = yield* Effect.sync(() => (process.platform === "win32" ? undefined : which("rg")))
            if (system && (yield* fs.isFile(system).pipe(Effect.orDie))) return system

            const target = path.join(Global.Path.bin, `rg${process.platform === "win32" ? ".exe" : ""}`)
            if (yield* fs.isFile(target).pipe(Effect.orDie)) return target

            const platformKey = `${process.arch}-${process.platform}` as keyof typeof PLATFORM
            const config = PLATFORM[platformKey]
            if (!config) throw new Error(`unsupported platform for ripgrep: ${platformKey}`)

            const filename = `ripgrep-${VERSION}-${config.platform}.${config.extension}`
            const url = `https://github.com/BurntSushi/ripgrep/releases/download/${VERSION}/${filename}`
            const archive = path.join(Global.Path.bin, filename)

            yield* Effect.logInfo("downloading ripgrep", { url })
            yield* fs.ensureDir(Global.Path.bin).pipe(Effect.orDie)
            const bytes = yield* HttpClientRequest.get(url).pipe(
              http.execute,
              Effect.flatMap((response) => response.arrayBuffer),
              Effect.mapError((cause) => (cause instanceof Error ? cause : new Error(String(cause)))),
            )
            if (bytes.byteLength === 0) throw new Error(`failed to download ripgrep from ${url}`)

            yield* fs.writeWithDirs(archive, new Uint8Array(bytes))
            yield* extract(archive, config, target)
            yield* fs.remove(archive, { force: true }).pipe(Effect.ignore)
            return target
          }),
        ),
      })
    }),
  )

  export const node = makeGlobalNode({
    service: Service,
    layer: layer,
    deps: [FSUtil.node, httpClient, CrossSpawnSpawner.node],
  })
}

