Interesting! `--max-columns=4000 --max-columns-preview` did NOT reduce the JSON record size - still 80254 bytes. So max-columns doesn't apply to JSON output mode in ripgrep 15.1.0!
Got it—let's skip the oversized JSON records entirely. I'll build a lightweight C# wrapper around `rg.exe` that:

- Passes all arguments through
- When `--json` is used, reads each line from `rg.exe`'s stdout
- If a line is longer than ~60 KB, skips it instead (keeps the exit code correct)
- Otherwise writes the line unchanged
- Returns the original exit code

This keeps the wrapper simple, streams, and matches the behavior you want.

Here's the core logic:

```csharp
using System;
using System.Diagnostics;
using System.IO;
using System.Text;

class RgWrapper // rename if you want
{
    static void Main(string[] args)
    {
        bool jsonMode = args.Any(a => a == "--json");

        if (!jsonMode)
        {
            // non-JSON: just run rg.exe normally
            var proc = new Process
            {
                StartInfo = new ProcessStartInfo
                {
                    FileName = "rg.exe",
                    Arguments = string.Join(" ", args),
                    UseShellExecute = false,
                    RedirectStandardOutput = false,
                    RedirectStandardError = false
                }
            };
            proc.Start();
            proc.WaitForExit();
            Environment.ExitCode = 0; // preserve original exit code
            return;
        }

        // JSON mode: wrap rg.exe and filter oversized lines
        var realRg = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "rg-real.exe");
        if (!File.Exists(realRg))
        {
            Console.Error.WriteLine("rg-json-cap rg-real.exe not found");
            Environment.ExitCode = 2;
            return;
        }

        var psi = new ProcessStartInfo
        {
            FileName = realRg,
            Arguments = string.Join(" ", args),
            UseShellExecute = false,
            CreateNoWindow = true,
            RedirectStandardOutput = true,
            StandardOutputEncoding  = Encoding.UTF8,
            RedirectStandardError   = false
        };

        var proc = Process.Start(psi);
        string line;
        while ((line = proc.StandardOutput.ReadLine()) != null)
        {
            if (Encoding.UTF8.GetByteCount(line) > 60000)
                continue; // skip oversized JSON records
            Console.Out.WriteLine(line);
        }

        proc.WaitForExit();
        Environment.ExitCode = proc.ExitCode;
    }
}
