// Caps ripgrep --json lines so Kilo/OpenCode do not abort with
// "Ripgrep JSON record exceeded 65536 bytes" on minified/one-line files.
// Real binary is rg-real.exe in this folder.
using System;
using System.Diagnostics;
using System.IO;
using System.Text;

internal static class Program
{
    const int MaxBytes = 60000;

    static int Main(string[] args)
    {
        string dir = AppDomain.CurrentDomain.BaseDirectory;
        string real = Path.Combine(dir, "rg-real.exe");
        if (!File.Exists(real))
        {
            Console.Error.WriteLine("rg-json-cap: rg-real.exe missing next to wrapper");
            return 2;
        }

        bool json = false;
        for (int i = 0; i < args.Length; i++)
        {
            if (args[i] == "--") break;
            if (args[i] == "--json") { json = true; break; }
        }

        var psi = new ProcessStartInfo();
        psi.FileName = real;
        psi.Arguments = QuoteArgs(args);
        psi.UseShellExecute = false;
        psi.CreateNoWindow = true;
        if (!json)
        {
            using (var p = Process.Start(psi))
            {
                p.WaitForExit();
                return p.ExitCode;
            }
        }

        psi.RedirectStandardOutput = true;
        psi.StandardOutputEncoding = new UTF8Encoding(false);
        using (var proc = Process.Start(psi))
        {
            Console.OutputEncoding = new UTF8Encoding(false);
            string line;
            while ((line = proc.StandardOutput.ReadLine()) != null)
            {
                if (Encoding.UTF8.GetByteCount(line) > MaxBytes)
                {
                    string stub = Shrink(line);
                    if (stub != null) Console.Out.WriteLine(stub);
                    continue;
                }
                Console.Out.WriteLine(line);
            }
            proc.WaitForExit();
            Console.Out.Flush();
            return proc.ExitCode;
        }
    }

    static string Shrink(string line)
    {
        bool match = line.IndexOf("\"type\":\"match\"", StringComparison.Ordinal) >= 0;
        bool context = line.IndexOf("\"type\":\"context\"", StringComparison.Ordinal) >= 0;
        if (!match && !context) return null;
        string path = ExtractPath(line);
        string num = ExtractLineNumber(line);
        if (path == null || num == null) return null;
        string kind = match ? "match" : "context";
        return "{\"type\":\"" + kind + "\",\"data\":{\"path\":{\"text\":\"" + path +
            "\"},\"lines\":{\"text\":\"[truncated line over 64KiB]\"},\"line_number\":" +
            num + ",\"absolute_offset\":0,\"submatches\":[]}}";
    }

    static string ExtractPath(string json)
    {
        const string key = "\"path\":{\"text\":\"";
        int i = json.IndexOf(key, StringComparison.Ordinal);
        if (i < 0) return null;
        i += key.Length;
        var sb = new StringBuilder();
        for (int j = i; j < json.Length; j++)
        {
            char c = json[j];
            if (c == '\\' && j + 1 < json.Length)
            {
                sb.Append(c);
                sb.Append(json[++j]);
                continue;
            }
            if (c == '"') break;
            sb.Append(c);
        }
        return sb.Length == 0 ? null : sb.ToString();
    }

    static string ExtractLineNumber(string json)
    {
        const string key = "\"line_number\":";
        int i = json.IndexOf(key, StringComparison.Ordinal);
        if (i < 0) return null;
        i += key.Length;
        int j = i;
        while (j < json.Length && json[j] >= '0' && json[j] <= '9') j++;
        return j == i ? null : json.Substring(i, j - i);
    }

    static string QuoteArgs(string[] args)
    {
        var sb = new StringBuilder();
        for (int i = 0; i < args.Length; i++)
        {
            if (i > 0) sb.Append(' ');
            sb.Append(Quote(args[i]));
        }
        return sb.ToString();
    }

    static string Quote(string arg)
    {
        if (arg.Length != 0 && arg.IndexOfAny(new char[] { ' ', '\t', '"', '\n' }) < 0)
            return arg;
        var sb = new StringBuilder();
        sb.Append('"');
        int bs = 0;
        foreach (char c in arg)
        {
            if (c == '\\') { bs++; continue; }
            if (c == '"')
            {
                sb.Append('\\', bs * 2 + 1);
                sb.Append('"');
                bs = 0;
                continue;
            }
            if (bs > 0) { sb.Append('\\', bs); bs = 0; }
            sb.Append(c);
        }
        if (bs > 0) sb.Append('\\', bs * 2);
        sb.Append('"');
        return sb.ToString();
    }
}

