var psi = new ProcessStartInfo();
psi.FileName = real;
psi.Arguments = QuoteArgs(args);
psi.UseShellExecute = false;
psi.CreateNoWindow = true;
psi.RedirectStandardOutput = true;
psi.RedirectStandardError = true;
psi.StandardOutputEncoding = new UTF8Encoding(false);
psi.StandardErrorEncoding = new UTF8Encoding(false);
using (var proc = Process.Start(psi))
{
    Stream errOut = Console.OpenStandardError();
    var errThread = new Thread(() => proc.StandardError.BaseStream.CopyTo(errOut));
    errThread.IsBackground = true;
    errThread.Start();
    if (json)
    {
        Console.OutputEncoding = new UTF8Encoding(false);
        string line;
        while ((line = proc.StandardOutput.ReadLine()) != null)
        {
            if (Encoding.UTF8.GetByteCount(line) > MaxBytes)
            {
                string stub = Shrink(line);
                if (stub != null) Console.Out.WriteLine(stub);
                continue;
            }
            Console.Out.WriteLine(line);
        }
        Console.Out.Flush();
    }
    else
    {
        proc.StandardOutput.BaseStream.CopyTo(Console.OpenStandardOutput());
    }
    proc.WaitForExit();
    errThread.Join();
    return proc.ExitCode;
}

